-- 3 Nov 2026: one brand list for every workspace. Merges duplicate brand rows (Clarins / Clarins-CMG …) into one master per brand,
-- group (CMG, IN, Amore, PWB, CPB, PFC, PVH, Reckitt) moves to brand_group, old spellings go to brands.aliases.
-- Re-points brand-field values on tasks and brand lists in custom_automations. Triggers are off for the transaction
-- (no automations, history rows or updated_at bumps). Backups: brand_merge_backup_{brands,tasks,autos}. Undo: 2026-11-03_brand_master_undo.sql.
-- Applied to production 3 Nov 2026 after a dry run (17,618 task values, 52 rows merged, 12 created, 19 CUSP suggestions, 25 rules).
begin;
set local session_replication_role = replica;
create table if not exists brand_merge_backup_brands as select now() as backed_up_at, b.* from brands b;
create table if not exists brand_merge_backup_autos as select now() as backed_up_at, id, conditions from custom_automations;
create table if not exists brand_merge_backup_tasks(task_id uuid, field_id text, old_value text, new_value text, changed_at timestamptz default now());
alter table brands add column if not exists aliases text[] not null default '{}', add column if not exists merged_into uuid references brands(id) on delete set null,
  add column if not exists cusp_shop text, add column if not exists cusp_country text, add column if not exists service_model text, add column if not exists category text;
create table if not exists brand_suggestions(id uuid primary key default gen_random_uuid(), company_id uuid references companies(id) on delete cascade,
  source text not null default 'cusp', kind text not null, brand_name text not null, cusp_shop text, country text, channels text[], service_model text, category text,
  detail text, status text not null default 'pending', created_at timestamptz default now(), decided_by uuid, decided_at timestamptz);
alter table brand_suggestions enable row level security;
do $p$ begin if not exists (select 1 from pg_policies where tablename='brand_suggestions') then
  create policy brand_suggestions_read on brand_suggestions for select using (company_id = (select company_id from profiles where id = auth.uid()));
  create policy brand_suggestions_admin on brand_suggestions for all using (exists (select 1 from profiles p where p.id = auth.uid() and p.role in ('admin','management') and p.company_id = brand_suggestions.company_id));
end if; end $p$;
