-- keeper = row already named like the master, else the first listed row
create temp table bk on commit drop as select bm.n, (select b.id from brands b where b.company_id='60117c82-7fe1-4190-95b1-0e4a96f0305e'::uuid and b.name = any(bm.r) and b.merged_into is null
   order by (b.name = bm.n) desc, array_position(bm.r, b.name) limit 1) keeper from bm where bm.act='keep';
create temp table bd on commit drop as select bk.n, bk.keeper, b.id dup from bk join bm using(n) join brands b on b.company_id='60117c82-7fe1-4190-95b1-0e4a96f0305e'::uuid and b.name = any(bm.r) and b.id <> bk.keeper;
update brand_stores x set brand_id=bd.keeper from bd where x.brand_id=bd.dup;
update brand_services x set brand_id=bd.keeper from bd where x.brand_id=bd.dup;
update onboarding_projects x set brand_id=bd.keeper from bd where x.brand_id=bd.dup;
update onboardings x set brand_id=bd.keeper from bd where x.brand_id=bd.dup;
update listing_campaigns x set brand_id=bd.keeper from bd where x.brand_id=bd.dup;
update brands k set name=bm.n, brand_group=bm.g, aliases=bm.a, cusp_shop=bm.cs, cusp_country=bm.cc, service_model=bm.sm, category=bm.cat,
  platforms=(select coalesce(array_agg(distinct p),'{}') from brands b, unnest(b.platforms) p where b.company_id='60117c82-7fe1-4190-95b1-0e4a96f0305e'::uuid and b.name = any(bm.r)),
  active=(select bool_or(b.active) from brands b where b.company_id='60117c82-7fe1-4190-95b1-0e4a96f0305e'::uuid and b.name = any(bm.r))
  from bk join bm using(n) where k.id = bk.keeper;
update brands b set active=false, merged_into=bd.keeper from bd where b.id=bd.dup;
insert into brands(company_id,name,brand_group,platforms,active,aliases,cusp_shop,cusp_country,service_model,category)
  select '60117c82-7fe1-4190-95b1-0e4a96f0305e'::uuid, n, g, ch, cs is not null, a, cs, cc, sm, cat from bm where act='new' and not exists (select 1 from brands b where b.company_id='60117c82-7fe1-4190-95b1-0e4a96f0305e'::uuid and b.name=bm.n);
insert into brand_suggestions(company_id,kind,brand_name,cusp_shop,country,channels,service_model,category,detail)
  select '60117c82-7fe1-4190-95b1-0e4a96f0305e'::uuid,'add',n,cs,cc,ch,sm,cat,'Active in CUSP but not in DONE' from bm where act='sugg' and not exists (select 1 from brand_suggestions s where s.brand_name=bm.n and s.kind='add');
do $t$ declare f record; begin
for f in select pf.id::text fid, pf.project_id from project_fields pf where pf.ftype='brand' loop
  with x as (select t.id, t.custom->>f.fid old,
      (select string_agg(p, ', ' order by o) from (select coalesce(m.new, trim(u.part)) p, min(u.o) o
         from unnest(string_to_array(t.custom->>f.fid, ',')) with ordinality u(part,o) left join bmap m on m.old = trim(u.part)
         where trim(u.part) <> '' group by 1) s) new
    from tasks t where t.project_id = f.project_id and coalesce(t.custom->>f.fid,'') <> ''),
  ch as (select * from x where new is not null and new <> old),
  ins as (insert into brand_merge_backup_tasks(task_id, field_id, old_value, new_value) select id, f.fid, old, new from ch returning 1)
  update tasks t set custom = jsonb_set(t.custom, array[f.fid], to_jsonb(ch.new)) from ch where t.id = ch.id;
end loop; end $t$;
update custom_automations c set conditions = (
  select jsonb_agg(case when jsonb_typeof(cond->'v')='array' and exists (select 1 from project_fields pf where 'field:'||pf.id::text = cond->>'k' and pf.ftype='brand')
    then jsonb_set(cond, '{v}', (select coalesce(jsonb_agg(p order by o),'[]') from (select coalesce(m.new, e.val) p, min(e.o) o
         from jsonb_array_elements_text(cond->'v') with ordinality e(val,o) left join bmap m on m.old=e.val group by 1) s))
    else cond end order by ord) from jsonb_array_elements(c.conditions) with ordinality a(cond, ord))
where jsonb_typeof(c.conditions)='array' and jsonb_array_length(c.conditions)>0;
commit;
